contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address from, address to, uint256 id) public {
        require(to != address(0), "INVALID_RECIPIENT");
        require(from != address(0), "ZERO_ADDRESS");

        // Ensure the token owner is `from` (mint is internal, so transferFrom would revert unless id already owned by from).
        // We cannot mint directly; we rely on `from` being a current owner only if it already owns id.
        // To make the transferFrom call meaningful without setup helpers, require that c.ownerOf(id) == from.
        address ownerBefore = c.ownerOf(id);
        require(ownerBefore == from, "from must be current owner");

        bool reverted;
        try c.transferFrom(from, to, id) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.ownerOf(id) == to);
        } else {
            assert(c.ownerOf(id) == from);
        }
    }

    receive() external payable {}
}

