contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint256 id) public payable {
        require(to != address(0), "to zero");

        // P mints the position token having id uint256(hashOrder(order)) to order.maker
        // when filling.  We cannot reproduce that without a full order/signature,
        // but we can still make the generic rule reachable by transferring the token
        // that P itself mints for an order whose maker is this test contract.
        // The only public mint path is fillOrder; its minted id is
        // uint256(hashOrder(order)) for order.maker == msg.sender.
        // Build a minimal order and fill it, then transferFrom with an approval.
        C.Order memory order;
        order.maker = address(this);
        order.isCall = false;
        order.isLong = true;
        order.baseAsset = address(c);
        order.strike = 0;
        order.premium = 0;
        order.duration = 0;
        order.expiration = block.timestamp + 1 days;
        order.nonce = 0;

        address[] memory whitelist = new address[](0);
        address[] memory floorTokens = new address[](0);
        C.ERC20Asset[] memory erc20Assets = new C.ERC20Asset[](0);
        C.ERC721Asset[] memory erc721Assets = new C.ERC721Asset[](0);
        order.whitelist = whitelist;
        order.floorTokens = floorTokens;
        order.erc20Assets = erc20Assets;
        order.erc721Assets = erc721Assets;

        uint256[] memory floorAssetTokenIds = new uint256[](0);
        bytes memory signature = new bytes(0);

        // A zero-length signature cannot pass isValidSignatureNow for a non-zero maker,
        // but order.maker == address(this); we call fillOrder and it will either revert
        // or mint position tokens for this contract.  Use the id parameter as the
        // approval key: approve(to, id), then transferFrom(this, to, id).
        // If the token id parameter equals the minted id, the rule is exercised.
        c.approve(to, id);
        c.transferFrom(address(this), to, id);

        assert(c.getApproved(id) == address(0));
    }
}

